const A=(v,i)=>(v+Math.floor(v/3)+1)%997;
const B=(v,i)=>v^(((i+1)*7)%64);
const C=(v,i)=>((v*3-i+1)%991+991)%991;
const D=(v,i)=>(v*2+2)%1000;
const F={A,B,C,D};
for(let i=1;i<=32;i++){
  const out=e.stages[i-1];let cands=[];
  for(const[k,f]of Object.entries(F)){for(let j=0;j<=40;j++){if(f(v,j)===out)cands.push(k+' i='+j)}}
  console.log(i,v,'->',out, cands.slice(0,6).join(', '));
  v=out;
}"

